1: // DOCUMENTS: the single-request hop-by-hop state machine behind the panel's
2: // "Step 1 Hop ->" trace — one hop per call, running across the same
3: // network/LB/queue/cache machinery the crowd uses (it does not fake a
4: // shortcut). 4 hops in Stage 1 (emit, route, serve, render); 5 in Stage 2
5: // (the LB's round-robin pick becomes its own hop); 6 in Stage 3 (the
6: // backend's cache-aside lookup and the HTTP response emission split in two);
7: // 7 in Stage 4 (the Database hop after the cache check — WRITE to Primary
8: // 10.30, fresh/stale SELECT from Replica 10.31, or SKIP on a warm HIT).
9: //
10: // The machine owns the trace state and hop transitions; the engine owns the
11: // clock, the served-exchange record, and browser delivery, handed in as the
12: // callbacks below. Stage 6 is delegated to its own machine in
13: // trace-stage6.js (a DNS ask/answer prelude in front of the byte-identical
14: // stage-5 chain), so the stage-1-to-5 conditions below are untouched.
15: // B-6 adds the stage-1 refusal branch (the transport refuses at the deliver
16: // hop); B-6b extends the shared LB hop — real selection read, all-down aborts at hop 3.
17: import { createStage6Trace } from './trace-stage6.js';
18: import * as hops from './trace-helpers.js';
19: const { backendFor, drainUntilYou, finishTo, serveInto } = hops;
20: 
21: // CHECKS: an out-of-range stage fails loud at construction instead of
22: // building a trace that can never advance.
23: export function createTraceMachine({
24:   stage,
25:   serverAddress,
26:   servers,
27:   lb = null,
28:   network,
29:   cache = null,
30:   database = null,
31:   workerQueue = null,
32:   dns = null,
33:   cdn = null,
34:   router = null,
35:   bumpTick,
36:   getTick,
37:   onServe,
38:   onFinish,
39:   onDnsFail = null,
40:   onRefusal = null,
41: }) {
42:   if (stage !== 1 && stage !== 2 && stage !== 3 && stage !== 4 && stage !== 5 && stage !== 6) {
43:     throw new Error(`trace: stage must be 1, 2, 3, 4, 5, or 6, got ${stage}`);
44:   }
45:   if (stage === 6) {
46:     return createStage6Trace({
47:       serverAddress,
48:       servers,
49:       lb,
50:       network,
51:       dns,
52:       cdn,
53:       router,
54:       cache,
55:       database,
56:       workerQueue,
57:       bumpTick,
58:       getTick,
59:       onServe,
60:       onFinish,
61:       onDnsFail,
62:     });
63:   }
64:   const RESET_FIELDS = {
65:     cacheStatus: null,
66:     dbOp: null,
67:     dbStale: false,
68:     response: null,
69:     status: null,
70:     body: null,
71:     routeId: null,
72:     refused: false,
73:   };
74: 
75:   let trace = freshTrace();
76:   let served = null; // the drained response record, held between hops 4/6 and 5/6
77: 
78:   function freshTrace() {
79:     return {
80:       hop: 0,
81:       method: 'GET',
82:       path: '/about',
83:       from: '10.2',
84:       request: 'GET /about',
85:       targetServer: null,
86:       ...RESET_FIELDS,
87:     };
88:   }
89: 
90:   return {
91:     // One hop per call. Returns the hop's lastFrame string, or null when
92:     // nothing moved (the engine keeps its previous frame then). A refused
93:     // delivery ends the stage-1 story at the deliver hop (2), a refused LB
94:     // hop (B-6b all-down) ends at 3; the served shape walks to the final hop.
95:     step({ method = 'GET', path = '/about', from = '10.2' } = {}) {
96:       const finalStageHop =
97:         stage === 5 ? 8 : stage === 4 ? 7 : stage === 3 ? 6 : stage === 2 ? 5 : 4;
98:       const finalHop = trace.refused ? (stage === 1 ? 2 : 3) : finalStageHop;
99:       let frame = null;
100:       if (trace.hop === 0 || trace.hop >= finalHop) {
101:         const request = `${method} ${path}`;
102:         trace = {
103:           ...freshTrace(),
104:           hop: 1,
105:           method,
106:           path,
107:           from,
108:           request,
109:           targetServer: stage === 1 ? serverAddress : null,
110:         };
111:         served = null;
112:         frame = `${from} -> ${serverAddress} | ${request}`;
113:       } else if (stage === 1 && trace.hop === 1) {
114:         trace.hop = 2;
115:         const atTick = bumpTick();
116:         const refusal = network.deliverToQueue({
117:           id: `you:${atTick}`,
118:           from: trace.from,
119:           to: serverAddress,
120:           request: trace.request,
121:           atTick,
122:           isYou: true,
123:         });
124:         if (refusal?.refused) {
125:           // CHECKS: B-6 counter-example, DL-3 — the refusal record ABORTS
126:           // the stage-1 story at the deliver hop: no queue entry (refused
127:           // before enqueue), no served record, response fields stay null so
128:           // trace.status carries no inherited 200/404, lastExchange
129:           // satisfies no mission detector, and the frame narrates the
130:           // refusal itself, not an HTTP status string.
131:           trace.refused = true;
132:           onRefusal?.(refusal);
133:           frame = `${trace.from} -> ${serverAddress} | ${trace.request} => connection refused (nothing enqueued)`;
134:         } else {
135:           frame = `routed ${trace.from} -> ${serverAddress} (${trace.request}) into queue`;
136:         }
137:       } else if (stage === 1 && trace.hop === 2) {
138:         trace.hop = 3;
139:         const you = drainUntilYou(servers[0], getTick);
140:         if (you) {
141:           serveInto(trace, you, onServe);
142:           frame = `${serverAddress} -> ${trace.from} | ${you.response}`;
143:         }
144:       } else if (stage === 1 && trace.hop === 3) {
145:         trace.hop = 4;
146:         finishTo(trace, serverAddress, onFinish);
147:       } else if (trace.hop === 1) {
148:         trace.hop = 2;
149:         frame = `routed ${trace.from} -> ${serverAddress} (${trace.request}) to LoadBalancer`;
150:       } else if (trace.hop === 2) {
151:         trace.hop = 3;
152:         const atTick = bumpTick();
153:         const target = lb.enqueue({
154:           id: `you:${atTick}`,
155:           from: trace.from,
156:           to: serverAddress,
157:           request: trace.request,
158:           atTick,
159:           isYou: true,
160:         });
161:         // CHECKS (B-6b): the frame reads the LB's own selection state —
162:         // lastSkip() names the crossed seat (no skip keeps the byte shape),
163:         // and an all-down record aborts here with no served data.
164:         if (target?.refused === true) {
165:           trace.refused = true;
166:           onRefusal?.(target);
167:           frame = hops.lbRefusedFrame(serverAddress, target, trace.request);
168:         } else {
169:           const skippedAt = lb.lastSkip?.();
170:           trace.targetServer = target;
171:           frame = hops.lbEnqueuedFrame(serverAddress, target, trace.request, skippedAt);
172:         }
173:       } else if (stage === 2 && trace.hop === 3) {
174:         trace.hop = 4;
175:         const backend = backendFor(servers, trace.targetServer);
176:         const you = drainUntilYou(backend, getTick);
177:         if (you) {
178:           serveInto(trace, you, onServe);
179:           frame = `${backend.address} -> ${trace.from} | ${you.response}`;
180:         }
181:       } else if (stage === 2 && trace.hop === 4) {
182:         trace.hop = 5;
183:         finishTo(trace, trace.targetServer ?? serverAddress, onFinish);
184:       } else if (stage === 3 && trace.hop === 3) {
185:         // Hop 4/6: the target backend checks Cache and serves the queued
186:         // request; the response record is held one hop so the learner sees
187:         // the cache lookup before the response leaves the backend.
188:         trace.hop = 4;
189:         const backend = backendFor(servers, trace.targetServer);
190:         served = drainUntilYou(backend, getTick);
191:         if (served) {
192:           trace.cacheStatus = served.cacheStatus ?? null;
193:           frame = `${backend.address} -> ${cache.address} | cache ${trace.cacheStatus} (${trace.path})`;
194:         }
195:       } else if (stage === 3 && trace.hop === 4) {
196:         trace.hop = 5;
197:         if (served) {
198:           serveInto(trace, served, onServe);
199:           frame = `${trace.targetServer} -> ${trace.from} | ${served.response} (${trace.cacheStatus})`;
200:         }
201:       } else if (stage === 3 && trace.hop === 5) {
202:         trace.hop = 6;
203:         finishTo(trace, trace.targetServer ?? serverAddress, onFinish);
204:       } else if (stage === 4 && trace.hop === 3) {
205:         // Hop 4/7: the target backend checks Cache and serves the queued
206:         // request (a POST write-through carries cacheStatus INVALIDATE);
207:         // the response record is held so the learner watches the cache
208:         // lookup, then the database hop.
209:         trace.hop = 4;
210:         const backend = backendFor(servers, trace.targetServer);
211:         served = drainUntilYou(backend, getTick);
212:         if (served) {
213:           trace.cacheStatus = served.cacheStatus ?? null;
214:           // B-6d: a refused write consults nothing — this hop names the
215:           // refusal honestly instead of narrating a raw "cache null".
216:           frame =
217:             served.dbOp === 'WRITE_DOWN'
218:               ? `${backend.address} -> ${cache.address} | write refused — cache not consulted (${trace.path})`
219:               : `${backend.address} -> ${cache.address} | cache ${trace.cacheStatus} (${trace.path})`;
220:         }
221:       } else if (stage === 4 && trace.hop === 4) {
222:         // Hop 5/7: the database hop — hop 6's WRITE landed on Primary
223:         // 10.30 (replication queued toward 10.31), the B-6d WRITE_DOWN
224:         // narrates a refused write, hop 5's SELECT read Replica 10.31
225:         // fresh or stale, and a warm cache HIT skips the database.
226:         trace.hop = 5;
227:         if (served) {
228:           trace.dbOp = served.dbOp ?? null;
229:           trace.dbStale = Boolean(served.dbStale);
230:           frame = hops.dbHopFrame(trace, database, cache);
231:         }
232:       } else if (stage === 4 && trace.hop === 5) {
233:         trace.hop = 6;
234:         if (served) {
235:           serveInto(trace, served, onServe);
236:           frame = `${trace.targetServer} -> ${trace.from} | ${served.response}${hops.serveCacheSuffix(trace)}`;
237:         }
238:       } else if (stage === 4 && trace.hop === 6) {
239:         trace.hop = 7;
240:         finishTo(trace, trace.targetServer ?? serverAddress, onFinish);
241:       } else if (stage === 5 && trace.hop === 3) {
242:         // Hop 4/8: an async POST /jobs enqueues to WorkerQueue 10.40; other
243:         // requests narrate the cache/database hop they actually took (the
244:         // Stage 4 story) — no phantom async jobs on GET traces (DL-4).
245:         trace.hop = 4;
246:         const backend = backendFor(servers, trace.targetServer);
247:         served = drainUntilYou(backend, getTick);
248:         if (served) {
249:           trace.cacheStatus = served.cacheStatus ?? null;
250:           trace.dbOp = served.dbOp ?? null;
251:           trace.dbStale = Boolean(served.dbStale);
252:           trace.asyncJob = Boolean(served.asyncJob);
253:           if (served.asyncJob) {
254:             frame = `${backend.address} -> ${workerQueue ? workerQueue.address : '10.40'} | enqueued async job (${trace.path})`;
255:           } else {
256:             frame = hops.dbHopFrame(trace, database, cache);
257:           }
258:         }
259:       } else if (stage === 5 && trace.hop === 4) {
260:         // Hop 5/8: the webserver answers — an immediate 202 for async jobs,
261:         // the actually-served response for everything else.
262:         trace.hop = 5;
263:         if (served) {
264:           serveInto(trace, served, onServe);
265:           frame = served.asyncJob
266:             ? `${trace.targetServer} -> ${trace.from} | ${served.response}`
267:             : `${trace.targetServer} -> ${trace.from} | ${served.response}${hops.serveCacheSuffix(trace)}`;
268:         }
269:       } else if (stage === 5 && trace.hop === 5) {
270:         // Hop 6/8: WebServer returns its response via Network
271:         trace.hop = 6;
272:         frame = `Network delivered ${trace.status} response to ${trace.from}`;
273:       } else if (stage === 5 && trace.hop === 6) {
274:         // Hop 7/8: Browser receives and displays the response
275:         trace.hop = 7;
276:         finishTo(trace, trace.targetServer ?? serverAddress, onFinish);
277:         frame = `Browser ${trace.from} received and displayed ${trace.status}`;
278:       } else if (stage === 5 && trace.hop === 7) {
279:         // CHECKS: B-6e — hop 8/8 tails with the worker's commit on an async
280:         // trace (a synchronous request finds the worker idle), and the
281:         // frame reads the LIVE queue state: a crashed worker's tail names
282:         // the crash and the waiting count, stamping no phantom commit
283:         // (DL-3).
284:         trace.hop = 8;
285:         frame = hops.workerTailFrame(trace, workerQueue, database);
286:       }
287:       return frame;
288:     },
289: 
290:     snapshot() {
291:       return { ...trace };
292:     },
293:   };
294: }

